/* Blackglass command access, without advancing the original campaign. */
(()=>{'use strict';const E=window.ApexEngine;let tab='command',notice='';const tabs={command:'Command',facilities:'Facilities',people:'People',ledger:'Treasury',canon:'Founding record'};const fmt=n=>Number(n).toLocaleString();
const card=(title,body)=>`<section class="apex-card"><h3>${title}</h3>${body}</section>`;
function state(){return E.ensure(DATA);}
function access(){const g=galaxyState();return g.currentLocationId==='blackglass_station'&&['docked','surface'].includes(g.phase);}
function content(){const a=state();if(tab==='command')return `<div class="apex-grid">${card('Founder clearance',`<span class="apex-tag">ROVAN KES / DEADLOCK</span><p>You lead The 3.2 Apex Protocol. Blackglass Station belongs to the syndicate.</p><p>${access()?'You are docked at Blackglass.':'Secure remote command link. Your ship remains at its current location.'}</p><button class="btn" data-apex-hq>Open HQ rooms →</button>`)}${card('Field identity',`<strong>${a.public?'Operating as Apex':'Operating personally'}</strong><p>${a.public?'New Lower Port cases are signed for Apex; their rewards go to the reserve. Clients learn your affiliation.':'New Lower Port cases pay your personal account. Your affiliation stays unannounced to new local contacts.'}</p><button class="btn" data-apex-public>${a.public?'Take future cases personally':'Represent Apex on future cases'}</button><p class="small muted">Existing cases keep the identity and payout account chosen when accepted. Known residents retain what you have already disclosed.</p>`)}${card('Council link / Jessa',`<span class="apex-tag">TECHNOLOGY & RESEARCH</span><p id="apexBrief">${esc(a.lastBrief||'Ask Jessa for a briefing based on the current station and field situation.')}</p><button class="btn" data-apex-brief>Request council briefing</button>`)}${card('Field record',`<div class="apex-number">${a.publicJobs.length}</div><p>Apex cases closed in the Lower Port.</p><p>Local standing: <strong>${a.standing>0?'+':''}${a.standing}</strong></p><p class="small muted">A gameplay measure of your public field decisions, starting at zero. It is not a historical empire-wide reputation score.</p>`)}</div>`;
if(tab==='facilities')return `<p>Established facilities inside Blackglass’s asteroid shell. These records do not purchase upgrades or advance time.</p><div class="apex-grid">${E.facilities.map(f=>card(esc(f.name),`<span class="apex-tag">${esc(f.status)}</span><p>${esc(f.note)}</p>${f.id==='lab'?'<button class="btn" data-apex-council>Contact Jessa →</button>':''}`)).join('')}</div><section class="apex-card"><h3>Kestrel flight line</h3><div class="apex-grid">${[128,129].map(n=>`<article class="apex-fighter"><span class="apex-serial">${n}</span><div><strong>Kestrel F-4 interceptor</strong><p>Flight-ready · Permanent pilot unappointed</p></div></article>`).join('')}</div><p class="muted">Fighter 129 was repaired during establishment. Deployment and pilot assignments remain player decisions.</p></section>`;
if(tab==='people')return `<div class="apex-grid">${E.people.map(p=>card(esc(p.name),`<span class="apex-tag">${esc(p.status)}</span><h4>${esc(p.role)}</h4><p>${esc(p.note)}</p>`)).join('')}</div>`;
if(tab==='ledger')return `<div class="apex-grid">${card('Apex reserve',`<div class="apex-number">${fmt(a.reserve)} <small>cr</small></div><p>Syndicate funds. Founding snapshot: 1,420,000 cr.</p>`)}${card('Personal funds',`<div class="apex-number">${fmt(DATA.character.credits)} <small>cr</small></div><p>Current campaign balance. Historical snapshot: 358,400 cr.</p>`)}</div>${card('Authorize a transfer',`<p>Move credits between your personal account and the Apex reserve. This creates a ledger entry; it earns no money or XP.</p><form id="apexTransfer"><div class="apex-form"><label>Direction<select id="apexDirection"><option value="deposit">Personal → Apex reserve</option><option value="withdraw">Apex reserve → Personal</option></select></label><label>Amount in credits<input id="apexAmount" type="number" min="1" step="1" inputmode="numeric" required placeholder="Enter amount"></label><button class="btn" type="submit">Authorize transfer</button></div></form>`)}${card('Reserve ledger',a.ledger.length?`<ol class="apex-ledger">${a.ledger.slice().reverse().map(l=>`<li><strong>${esc(l.text)}</strong><p>${l.delta>=0?'+':''}${fmt(l.delta)} cr · Balance ${fmt(l.balance)} cr</p></li>`).join('')}</ol>`:'<p>No new transactions. Founding purchases and the heist are historical records, not new charges or payouts.</p>')}`;
return `<div class="apex-grid">${card('The heist that named us',`<span class="apex-tag">3.2 MILLION CREDITS</span><p>The 3.2 Apex Protocol takes its name from the successful 3.2-million-credit heist. Rovan Kes founded and leads the organization.</p><p>Bounty-hunter clan first: secure HQ, Jessa’s research, armory and hangar. Fighters first; cargo ships later.</p>`)}${card('Blackglass acquisition',`<p>Blackglass Station and both Kestrel F-4s were purchased for <strong>650,000 credits</strong>. Establishment work was budgeted at 780,000 credits. The seller signed an NDA.</p><p>A decommissioned repair installation buried inside an asteroid. Only the armored docking throat breaks the rock’s surface.</p>`)}${card('Preserved campaign decisions',`<p>Jessa accepted a permanent founding council seat for Technology and Research. Sera remains a free contact. Dren and Krail’s proposed fees are unaccepted and unpaid.</p><p>The recovered Rusk briefing remains archival: 160,000 alive / 80,000 dead, +40,000 for an intact convoy. Six in-game hours remained at that snapshot. This update starts no countdown or deployment.</p>`)}${card('Continuity notes',`<p>The current game’s Blackglass map node and Raven name are preserved. The original tabletop record did not specify Blackglass’s exact star system; Kaelor is the game map placement.</p><p>Existing personal funds, contracts, injuries and district progress are preserved. New campaigns use the 358,400-credit personal snapshot.</p><p>A formal charter, additional members and permanent fighter pilots remain undecided.</p>`)}</div>`;}
function page(){const a=state();return `<section class="apex-shell"><header class="apex-hero"><img src="assets/scenes/blackglass_asteroid_v17.svg" alt="Blackglass’s armored docking throat recessed inside an asteroid"><div><span class="micro">BLACKGLASS STATION / ${access()?'DOCKED':'SECURE REMOTE LINK'}</span><h2>The 3.2<br>Apex Protocol</h2><p>Founded by Rovan Kes. Named for the 3.2-million-credit heist.</p></div></header><nav class="apex-tabs" aria-label="Syndicate sections">${Object.entries(tabs).map(([id,label])=>`<button class="btn ${tab===id?'active':''}" data-apex-tab="${id}" aria-pressed="${tab===id}">${label}</button>`).join('')}</nav><p id="apexNotice" class="apex-notice" role="status">${esc(notice||'Founder authentication confirmed. Welcome back, Deadlock.')}</p><div id="apexBody">${content()}</div></section>`;}
function afterRender(pageName){if(!pages.includes('Syndicate')){pages.splice(pages.indexOf('HQ')+1,0,'Syndicate');buildNav();document.querySelectorAll('#nav button').forEach(b=>b.classList.toggle('active',b.textContent===pageName));}if(['HQ','Overview','Factions'].includes(pageName)){const n=document.createElement('section');n.className='apex-entry';n.innerHTML=`<div><span class="micro">FOUNDER / ROVAN KES</span><strong>The 3.2 Apex Protocol</strong><p>Blackglass is your syndicate HQ. Command, people, facilities and separate treasury.</p></div><button class="btn" data-apex-enter>Open Syndicate →</button>`;document.querySelector('#content').prepend(n);n.querySelector('button').onclick=()=>render('Syndicate');}
if(pageName!=='Syndicate')return;document.querySelectorAll('[data-apex-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.apexTab;notice='';render('Syndicate');document.querySelector('.apex-tabs').scrollIntoView({block:'start',behavior:'instant'});});document.querySelector('[data-apex-hq]')?.addEventListener('click',()=>render('HQ'));document.querySelector('[data-apex-council]')?.addEventListener('click',()=>{tab='command';render('Syndicate');});document.querySelector('[data-apex-public]')?.addEventListener('click',()=>{const a=state();a.public=!a.public;notice=a.public?'Future Lower Port cases will represent Apex and pay the reserve.':'Future Lower Port cases will be personal. Existing commitments remain unchanged.';save();render('Syndicate');});document.querySelector('[data-apex-brief]')?.addEventListener('click',()=>{const a=state();a.lastBrief=E.brief(DATA);save();document.querySelector('#apexBrief').textContent=a.lastBrief;});document.querySelector('#apexTransfer')?.addEventListener('submit',e=>{e.preventDefault();if(forcedEncounterPage())return;const result=E.transfer(DATA,document.querySelector('#apexDirection').value,Number(document.querySelector('#apexAmount').value));notice=result.message;if(result.ok)save();render('Syndicate');});}
window.pageSyndicate=page;window.DeadlockApex={afterRender};
})();
